class Solution {
    int parse(const string& s, int& i) {
        vector<long> stack;
        long num = 0;
        char sign = '+';
        while (i < (int)s.length()) {
            char ch = s[i++];
            if (ch == ' ') continue;
            if (isdigit(ch)) {
                num = num * 10 + (ch - '0');
            } else if (ch == '(') {
                num = parse(s, i);
            }
            if ((!isdigit(ch) && ch != ' ') || i == (int)s.length()) {
                if (sign == '+') stack.push_back(num);
                else if (sign == '-') stack.push_back(-num);
                else if (sign == '*') stack.back() *= num;
                else if (sign == '/') stack.back() /= num;
                sign = ch;
                num = 0;
            }
            if (ch == ')') break;
        }
        long sum = 0;
        for (long x : stack) sum += x;
        return (int)sum;
    }
public:
    int calculate(string s) {
        int i = 0;
        return parse(s, i);
    }
};

class Solution {
    private int i = 0;
    public int calculate(String s) {
        return parse(s);
    }
    private int parse(String s) {
        Deque<Integer> stack = new ArrayDeque<>();
        int num = 0;
        char sign = '+';
        while (i < s.length()) {
            char ch = s.charAt(i++);
            if (Character.isDigit(ch)) {
                num = num * 10 + (ch - '0');
            } else if (ch == '(') {
                num = parse(s);
            }
            if ((!Character.isDigit(ch) && ch != ' ') || i == s.length()) {
                if (sign == '+') stack.push(num);
                else if (sign == '-') stack.push(-num);
                else if (sign == '*') stack.push(stack.pop() * num);
                else if (sign == '/') stack.push(stack.pop() / num);
                sign = ch;
                num = 0;
            }
            if (ch == ')') break;
        }
        int sum = 0;
        for (int x : stack) sum += x;
        return sum;
    }
}

var calculate = function(s) {
    let i = 0;
    function parse() {
        const stack = [];
        let num = 0;
        let sign = '+';
        while (i < s.length) {
            const ch = s[i++];
            if (ch >= '0' && ch <= '9') {
                num = num * 10 + Number(ch);
            } else if (ch === '(') {
                num = parse();
            }
            if ((ch < '0' || ch > '9') && ch !== ' ' || i === s.length) {
                if (sign === '+') stack.push(num);
                else if (sign === '-') stack.push(-num);
                else if (sign === '*') stack.push(stack.pop() * num);
                else if (sign === '/') stack.push(Math.trunc(stack.pop() / num));
                sign = ch;
                num = 0;
            }
            if (ch === ')') break;
        }
        return stack.reduce((acc, val) => acc + val, 0);
